#!/usr/bin/env node
/*
 * Builds supabase/as24_apply_0129-0141.sql: every migration the Autosleutel24
 * database (utctfircycpjmpjqmtmm) still needs, in order, in ONE transaction —
 * all or nothing.
 *
 * State it is for: the read-only probe of 22 Nov 2026 found 0089-0128 applied
 * and 0129-0140 plus the conversion table (0141, written as 0109 on branch
 * claude/ads-conversion-upload) missing.
 *
 *   node scripts/build-as24-migration-bundle.mjs           write the bundle
 *   node scripts/build-as24-migration-bundle.mjs --check   exit 1 when the committed bundle is stale
 *
 * Writes a file only. It never connects to a database.
 */
import { createHash } from 'node:crypto';
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { transactionProblem } from './build-kfc-migration-bundle.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const MIGRATIONS = join(ROOT, 'supabase', 'migrations');
export const OUTPUT = join(ROOT, 'supabase', 'as24_apply_0129-0141.sql');
export const FIRST = 129;
export const LAST = 141;

const pad = (number) => String(number).padStart(4, '0');

/** Exactly one NNNN_*.sql per number from FIRST to LAST, in order. */
export function selectMigrations(names) {
  const byNumber = new Map();
  for (const name of names) {
    if (!/^\d{4}_.+\.sql$/.test(name)) continue;
    const number = Number(name.slice(0, 4));
    if (number < FIRST || number > LAST) continue;
    byNumber.set(number, [...(byNumber.get(number) ?? []), name]);
  }
  const files = [];
  for (let number = FIRST; number <= LAST; number += 1) {
    const found = byNumber.get(number) ?? [];
    if (found.length !== 1) throw new Error(`Migration ${pad(number)}: expected one file, found ${found.length} (${found.join(', ') || 'none'}).`);
    files.push(found[0]);
  }
  return files;
}

export function buildBundle(migrations) {
  for (const { name, sql } of migrations) {
    const problem = transactionProblem(sql);
    if (problem) throw new Error(`${name} cannot run inside the bundle's transaction: ${problem}`);
  }
  const list = migrations.map(({ name, sql }) => `--   ${name}  sha256:${createHash('sha256').update(sql).digest('hex').slice(0, 12)}`);
  const header = [
    '-- Autosleutel24 database (utctfircycpjmpjqmtmm): migrations 0129-0141, all or nothing.',
    '-- GENERATED by scripts/build-as24-migration-bundle.mjs — do not edit; rebuild after merges.',
    '-- Run ONCE in the Supabase SQL editor of the Autosleutel24 project, after a backup.',
    '-- If any statement fails, nothing is changed.',
    '--',
    '-- For a database at 0128 (probe of 22 Nov 2026: 0089-0128 applied, 0129-0140 missing).',
    '-- Refuses: a database not at 0128, any database that already has one of 0129-0141',
    '-- (KeyForCars, or this file run a second time), and a database with no jobs.',
    '-- Ends by marking the database as autosleutel24 in public.crm_install (0133).',
    '--',
    '-- Contains:',
    ...list,
    '',
    'begin;',
    '',
    '-- Refuse the wrong database before touching anything. Tables that may be',
    '-- missing are read with EXECUTE, so the block plans on any database.',
    'do $$',
    'declare v_jobs boolean;',
    'begin',
    "  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'expenses' and column_name = 'purchase_order_id') then",
    "    raise exception 'This database is not at migration 0128 (expenses.purchase_order_id missing). Stop: wrong project, or 0089-0128 not applied.';",
    '  end if;',
    "  if to_regclass('public.kfc_pos_sessions') is not null or to_regclass('public.crm_install') is not null",
    "     or to_regclass('public.kfc_period_lock') is not null or to_regclass('public.ad_conversion_matches') is not null then",
    "    raise exception 'This database already has part of 0129-0141 (KeyForCars, or this file has run before). Stop.';",
    '  end if;',
    "  execute 'select exists (select 1 from public.jobs)' into v_jobs;",
    '  if not v_jobs then',
    "    raise exception 'This database has no jobs: not the live Autosleutel24 database. Stop.';",
    '  end if;',
    'end',
    '$$;',
    '',
  ];
  const body = migrations.flatMap(({ name, sql }) => [`-- ===== ${name} =====`, sql.trimEnd(), '']);
  const footer = [
    '-- ===== install marker (0133: set by hand once per database) =====',
    "insert into public.crm_install (profile) values ('autosleutel24');",
    '',
    'commit;',
    '',
  ];
  return [...header, ...body, ...footer].join('\n');
}

export function buildFromDisk() {
  const files = selectMigrations(readdirSync(MIGRATIONS));
  const migrations = files.map((name) => ({ name, sql: readFileSync(join(MIGRATIONS, name), 'utf8') }));
  return { sql: buildBundle(migrations), files };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { sql, files } = buildFromDisk();
  if (process.argv.includes('--check')) {
    const current = existsSync(OUTPUT) ? readFileSync(OUTPUT, 'utf8') : '';
    if (current !== sql) {
      console.error('supabase/as24_apply_0129-0141.sql is stale: run node scripts/build-as24-migration-bundle.mjs');
      process.exit(1);
    }
    console.log('Bundle is up to date.');
  } else {
    writeFileSync(OUTPUT, sql);
    console.log(`Wrote ${OUTPUT} with ${files.length} migrations (${files[0]} … ${files.at(-1)}).`);
  }
}
